      root.appendChild(el('nav', { class: 'mfb-nav', 'aria-label': str('plNavAria') },
        el('a', { class: 'mfb-btn mfb-btn--ghost', href: '#jidelnicek', 'aria-current': current === 'plan' ? 'page' : null }, el('span', { class: 'mfb-btn__ico' }, icon(IC.calendar)), str('plTitle')),
        el('a', { class: 'mfb-btn mfb-btn--ghost', href: '#seznam', 'aria-current': current === 'list' ? 'page' : null }, el('span', { class: 'mfb-btn__ico' }, icon(IC.list)), str('listTitle'))));
