  /* ================================================================== routes */
  function go(view, W, pid) {
    if (view === 'seznam') location.hash = 'seznam';
    else if (view === 'recept') location.hash = 'recept=' + pid;
    else { if (W) UI.W = W; if (location.hash === '#jidelnicek') { UI.view = 'plan'; render(); window.scrollTo(0, 0); } else location.hash = 'jidelnicek'; }
  }
  const replaceHash = (h) => { try { history.replaceState(null, '', location.pathname + location.search + (h ? '#' + h : '')); } catch (e) { /* ignore */ } };
  async function route() {
    const h = decodeURIComponent(location.hash.slice(1));
    let m;
    closeDialog(true);
    MSG = null;
    if (h === 'seznam') { UI.view = 'list'; render(); window.scrollTo(0, 0); return; }
    if ((m = h.match(/^recept=(\d+)$/))) { UI.view = 'recipe'; UI.pid = Number(m[1]); render(); window.scrollTo(0, 0); return; }
    UI.view = 'plan';
    if ((m = h.match(/^tyden=([\w-]+)$/))) {
      replaceHash('jidelnicek');
      render();
      const s = SAMPLES.find((x) => x.k === m[1]);
      if (s) openApply({ sample: s });
      else { setMsg('sum', [str('plBadLink')], { alert: true }); render(); }
      return;
    }
    if ((m = h.match(/^plan=([A-Za-z0-9_-]+)$/))) {
      replaceHash('jidelnicek');
      render();
      try { const link = await decodePlan(m[1]); if (!link.w.length) throw new Error('empty'); openApply({ link }); } catch (e) { setMsg('sum', [str('plBadLink')], { alert: true }); render(); }
      return;
    }
    if ((m = h.match(/^nakup=(\d{4}-\d{2}-\d{2})$/))) {
      replaceHash('jidelnicek');
      const w = wk0();
      if (m[1] === w.W0 || m[1] === w.W1) UI.W = m[1];
      UI.focus = '[data-send]';
      render();
      const b = APP.querySelector('[data-send]') || APP.querySelector('#mfb-sum');
      if (b) { b.scrollIntoView({ block: 'center' }); focusEl(b); }
      return;
    }
    render();
    window.scrollTo(0, 0);
  }

  /* ================================================================== prototype banner + boot */
